pragma solidity >=0.8.0;

contract IntWide {
    int128 public sar128;
    int128 public sdiv128;
    int128 public smod128;
    int64  public cast64;
    int256 public sdiv256;
    int256 public smod256;
    uint256 public shr256;
    uint256 public count;
    uint256 public boomResult;

    function packCore(int128 x, uint256 y) external {
        sar128 = x >> 5;
        sdiv128 = x / 7;
        smod128 = x % 7;
        int256 sy = int256(y);
        sdiv256 = sy / 13;
        smod256 = sy % 13;
        shr256 = y >> 200;
        uint64 u = uint64(y);
        cast64 = int64(u);
        count++;
    }

    function boomDiv(int8 a) external returns (int8) {
        boomResult = 1;
        int8 r = a / (-1);
        boomResult = 0;
        count++;
        return r;
    }
}
